def fraction_to_decimal(numerator: int, denominator: int) -> str:
    if denominator == 0:
        return '0'

    result = []
    if numerator < 0 and denominator > 0 or numerator > 0 and denominator < 0:
        result.append('-')

    numerator, denominator = abs(numerator), abs(denominator)
    result.append(str(numerator // denominator))
    remainder = numerator % denominator
    if remainder == 0:
        return ''.join(result)

    result.append('.')
    decimal_part = {}

    while remainder != 0:
        if remainder in decimal_part:
            result.insert(decimal_part[remainder], '(')
            result.append(')')
            break

        decimal_part[remainder] = len(result)
        remainder *= 10
        result.append(str(remainder // denominator))
        remainder %= denominator

    return ''.join(result)

def fraction_to_decimal(numerator: int, denominator: int) -> str:
    """Convert a fraction to a decimal string. If the decimal part repeats, enclose the repeating part in parentheses. Handle negative numbers and division by zero (return '0')."""

    if numerator == 0: 
        return '0'
    if denominator == 0: 
        return ''

    result = []
    if (numerator < 0) ^ (denominator < 0):
        result.append('-')

    numerator, denominator = abs(numerator), abs(denominator)
    integer_part, remainder = divmod(numerator, denominator)
    result.append(str(integer_part))

    if remainder == 0:
        return ''.join(result)

    result.append('.')
    decimal_part = []
    seen_remainders = {}

    while remainder != 0:
        if remainder in seen_remainders:
            decimal_part.insert(seen_remainders[remainder], '(')
            decimal_part.append(')')
            break

        seen_remainders[remainder] = len(decimal_part)
        quotient, remainder = divmod(remainder * 10, denominator)
        decimal_part.append(str(quotient))

    return ''.join(result + decimal_part)

