    def justify(line, max_width, is_last_line=False):
        if len(line) == 1 or is_last_line:
            return ' '.join(line).ljust(max_width)
        spaces = max_width - sum(len(word) for word in line)
        num_gaps = len(line) - 1
        if num_gaps == 0:
            return line[0].ljust(max_width)
        spaces_per_gap = spaces // num_gaps
        extra_spaces = spaces % num_gaps
        justified_line = []
        for i in range(num_gaps):
            justified_line.append(line[i])
            justified_line.append(' ' * (spaces_per_gap + 1))
            if i < extra_spaces:
                justified_line.append(' ')
        justified_line.append(line[-1])
        return ''.join(justified_line).ljust(max_width)

    lines, current_line, current_length = [], [], 0

    for word in words:
        if current_length + len(word) + len(current_line) > max_width:
            lines.append(justify(current_line, max_width))
            current_line, current_length = [], 0
        current_line.append(word)
        current_length += len(word)

    lines.append(justify(current_line, max_width, is_last_line=True))

    return lines

