def parse_bool_expr(expression: str) -> bool:
    import re

    # Define the mapping of boolean values
    bool_map = {'t': True, 'f': False}

    # Helper function to evaluate a single boolean expression
    def eval_expr(expr: str) -> bool:
        try:
            # Replace 't' and 'f' with True and False
            expr = re.sub(r't', 'True', expr)
            expr = re.sub(r'f', 'False', expr)
            # Evaluate the expression
            return eval(expr)
        except Exception:
            return False

    # Handle nested expressions
    def handle_nested(expr: str) -> str:
        while '!(t)' in expr or '!(f)' in expr or '!(True)' in expr or '!(False)' in expr:
            expr = re.sub(r'!(t)', 'f', expr)
            expr = re.sub(r'!(f)', 't', expr)
            expr = re.sub(r'!(True)', 'False', expr)
            expr = re.sub(r'!(False)', 'True', expr)
        return expr

    # Preprocess the expression to handle nested not operations
    expression = handle_nested(expression)

    # Split the expression by operators and evaluate
    tokens = re.split(r'(\|\||&&|\!)', expression)
    result = bool_map[tokens[0]]

    for i in range(1, len(tokens), 2):
        op = tokens[i]
        val = tokens[i + 1]
        if op == '&&':
            result &= bool_map[val]
        elif op == '||':
            result |= bool_map[val]
        elif op == '!':
            result = not bool_map[val]

    return result

