from collections import deque

def expand_braces(s: str) -> list:
    def parse_braces(s: str) -> list:
        stack, parts, current = [], [], deque()
        for char in s:
            if char == '{':
                if current:
                    parts.append(''.join(current))
                    current = []
                stack.append(parts)
                parts = []
            elif char == '}':
                if current:
                    parts.append(''.join(current))
                    current = []
                parts = stack.pop() + parts
            else:
                current.append(char)
        if current:
            parts.append(''.join(current))
        return parts

    def expand(parts: list) -> list:
        if not parts:
            return ['']
        result = ['']
        for part in parts:
            if '{' in part:
                expanded_parts = parse_braces(part)
                result = [prefix + suffix for prefix in result for suffix in expanded_parts]
            else:
                result = [prefix + part for prefix in result]
        return result

    parts = parse_braces(s)
    result = expand(parts)
    return sorted(result)

