    def dfs(board: str, hand: str, steps: int, cache) -> int:
        if board in cache:
            return cache[board]
        if not board:
            return steps
        min_steps = float('inf')
        for i in range(len(board)):
            for j in range(len(hand)):
                new_board = board[:i] + hand[j] + board[i:]
                cleared_board = clear(new_board)
                if len(cleared_board) < len(board):
                    min_steps = min(min_steps, dfs(cleared_board, hand[:j] + hand[j+1:], steps + 1, cache))
        cache[board] = min_steps if min_steps != float('inf') else -1
        return cache[board]

    cache = {}
    return dfs(board, hand, 0, cache)

from collections import Counter
import itertools

def find_min_steps_zuma(board: str, hand: str) -> int:
    if not board and not hand:
        return 0

    if not board:
        return -1 if any(count > 2 for color, count in Counter(hand).items()) else len(hand)

    if not hand:
        return len(board)

    def remove_group(s: str) -> str:
        groups = [tuple(g) for _, g in itertools.groupby(s)]
        removed = True
        while removed:
            removed = False
            for group in groups:
                if len(group) >= 3:
                    s = s.replace(group, '', 1)
                    groups = [tuple(g) for _, g in itertools.groupby(s)]
                    removed = True
                    break
        return s

    def dfs(board: str, hand: str) -> int:
        if not board:
            return 0
        min_steps = float('inf')
        for i in range(len(board)):
            for color, count in Counter(hand).items():
                for _ in range(count + 1):
                    new_board = board[:i] + color + board[i:]
                    new_board = remove_group(new_board)
                    steps = dfs(new_board, hand.replace(color, '', 1))
                    if steps >= 0:
                        min_steps = min(min_steps, 1 + steps)
        return -1 if min_steps == float('inf') else min_steps

    return dfs(board, hand)
